CREATE TRIGGER api_tokens_scopes_insert BEFORE INSERT ON api_tokens BEGIN
SELECT RAISE (ABORT, 'api token scopes') WHERE EXISTS (SELECT 1 FROM json_each (NEW.scopes) WHERE type <> 'text' OR value NOT IN ('documents.read', 'documents.write', 'tasks.read', 'tasks.write', 'projects.read', 'projects.manage', 'share.manage', 'workspace.manage'));
END

CREATE TRIGGER api_tokens_scopes_update BEFORE UPDATE OF scopes ON api_tokens BEGIN
SELECT RAISE (ABORT, 'api token scopes') WHERE EXISTS (SELECT 1 FROM json_each (NEW.scopes) WHERE type <> 'text' OR value NOT IN ('documents.read', 'documents.write', 'tasks.read', 'tasks.write', 'projects.read', 'projects.manage', 'share.manage', 'workspace.manage'));
END

CREATE TRIGGER attachment_object_cleanups_after_attachment_delete AFTER DELETE ON attachments BEGIN
INSERT INTO attachment_object_cleanups (id, workspace_id, attachment_id, storage_key) VALUES (randomblob (16), OLD.workspace_id, OLD.id, OLD.storage_key);
INSERT INTO attachment_object_cleanups (id, workspace_id, attachment_id, storage_key) SELECT randomblob (16), OLD.workspace_id, OLD.id, json_extract (OLD.variants, '$.preview.key') WHERE json_type (OLD.variants, '$.preview.key') = 'text';
END

CREATE TRIGGER collection_fields_identity BEFORE UPDATE ON collection_fields WHEN NEW.workspace_id IS NOT OLD.workspace_id OR NEW.collection_id IS NOT OLD.collection_id OR NEW.KEY IS NOT OLD.KEY OR NEW.type IS NOT OLD.type BEGIN
SELECT RAISE (ABORT, 'field identity is immutable');
END

CREATE TRIGGER collection_items_scope_insert BEFORE INSERT ON collection_items BEGIN
SELECT RAISE (ABORT, 'collection scope mismatch') WHERE NOT EXISTS (SELECT 1 FROM collections c LEFT JOIN documents d ON d.workspace_id = NEW.workspace_id AND d.id = NEW.document_id LEFT JOIN tasks t ON t.workspace_id = NEW.workspace_id AND t.id = NEW.task_id WHERE c.workspace_id = NEW.workspace_id AND c.id = NEW.collection_id AND ((NEW.document_id IS NOT NULL AND c.kind = 'document' AND d.id IS NOT NULL AND c.project_id IS d.project_id) OR (NEW.task_id IS NOT NULL AND c.kind = 'task' AND t.id IS NOT NULL AND c.project_id IS t.project_id)));
END

CREATE TRIGGER collection_items_scope_update BEFORE UPDATE OF collection_id, document_id, task_id, workspace_id ON collection_items BEGIN
SELECT RAISE (ABORT, 'collection scope mismatch') WHERE NOT EXISTS (SELECT 1 FROM collections c LEFT JOIN documents d ON d.workspace_id = NEW.workspace_id AND d.id = NEW.document_id LEFT JOIN tasks t ON t.workspace_id = NEW.workspace_id AND t.id = NEW.task_id WHERE c.workspace_id = NEW.workspace_id AND c.id = NEW.collection_id AND ((NEW.document_id IS NOT NULL AND c.kind = 'document' AND d.id IS NOT NULL AND c.project_id IS d.project_id) OR (NEW.task_id IS NOT NULL AND c.kind = 'task' AND t.id IS NOT NULL AND c.project_id IS t.project_id)));
END

CREATE TRIGGER collections_keep_scope BEFORE UPDATE OF workspace_id, project_id, kind ON collections WHEN (NEW.workspace_id IS NOT OLD.workspace_id OR NEW.project_id IS NOT OLD.project_id OR NEW.kind IS NOT OLD.kind) AND EXISTS (SELECT 1 FROM collection_items WHERE collection_id = OLD.id) BEGIN
SELECT RAISE (ABORT, 'populated collection scope is immutable');
END

CREATE TRIGGER documents_keep_collection_scope BEFORE UPDATE OF workspace_id, project_id ON documents WHEN (NEW.workspace_id IS NOT OLD.workspace_id OR NEW.project_id IS NOT OLD.project_id) AND EXISTS (SELECT 1 FROM collection_items WHERE document_id = OLD.id) BEGIN
SELECT RAISE (ABORT, 'detach document before changing scope');
END

CREATE TRIGGER documents_path_insert BEFORE INSERT ON documents BEGIN
SELECT RAISE (ABORT, 'documents path segment') WHERE EXISTS (WITH RECURSIVE segments (rest, segment) AS (SELECT NEW.path || '.', '' UNION ALL SELECT substr (rest, instr (rest, '.') + 1), substr (rest, 1, instr (rest, '.') - 1) FROM segments WHERE rest <> '') SELECT 1 FROM segments WHERE rest <> NEW.path || '.' AND length (segment) <> 32);
END

CREATE TRIGGER documents_path_update BEFORE UPDATE OF path ON documents BEGIN
SELECT RAISE (ABORT, 'documents path segment') WHERE EXISTS (WITH RECURSIVE segments (rest, segment) AS (SELECT NEW.path || '.', '' UNION ALL SELECT substr (rest, instr (rest, '.') + 1), substr (rest, 1, instr (rest, '.') - 1) FROM segments WHERE rest <> '') SELECT 1 FROM segments WHERE rest <> NEW.path || '.' AND length (segment) <> 32);
END

CREATE TRIGGER event_sequence_no_delete BEFORE DELETE ON event_sequence BEGIN
SELECT RAISE (ABORT, 'event sequence cannot be deleted');
END

CREATE TRIGGER event_sequence_no_replace BEFORE INSERT ON event_sequence WHEN EXISTS (SELECT 1 FROM event_sequence) BEGIN
SELECT RAISE (ABORT, 'event sequence already exists');
END

CREATE TRIGGER event_sequence_no_reset BEFORE UPDATE ON event_sequence WHEN NEW.id <> OLD.id OR NEW.last_seq < OLD.last_seq BEGIN
SELECT RAISE (ABORT, 'event sequence cannot be reset');
END

