CREATE TRIGGER task_timer_legacy_tracking_close AFTER UPDATE ON time_entries WHEN OLD.ended_at IS NULL AND NEW.ended_at IS NOT NULL BEGIN
DELETE FROM task_timer_legacy_open WHERE time_entry_id = NEW.id;
END

CREATE TRIGGER task_timer_legacy_tracking_insert AFTER INSERT ON time_entries WHEN NEW.ended_at IS NULL BEGIN
SELECT RAISE (ABORT, 'open time entry exists') WHERE EXISTS (SELECT 1 FROM task_timer_runs WHERE user_id = NEW.user_id AND status <> 'stopped') OR EXISTS (SELECT 1 FROM task_timer_legacy_open WHERE user_id = NEW.user_id);
INSERT INTO task_timer_legacy_open (time_entry_id, user_id, workspace_id, task_id) VALUES (NEW.id, NEW.user_id, NEW.workspace_id, NEW.task_id);
END

CREATE TRIGGER tasks_keep_collection_scope BEFORE UPDATE OF workspace_id, project_id ON tasks WHEN (NEW.workspace_id IS NOT OLD.workspace_id OR NEW.project_id IS NOT OLD.project_id) AND EXISTS (SELECT 1 FROM collection_items WHERE task_id = OLD.id) BEGIN
SELECT RAISE (ABORT, 'detach task before changing scope');
END

CREATE TRIGGER timer_segment_time_entry_purge BEFORE DELETE ON time_entries BEGIN
